/* @lc app=leetcode id=3734 lang=kotlin */ class Solution { fun lexPalindromicPermutation(s: String, target: String): String = s.length.let { n -> (n / 2).let { h -> IntArray(26).also { c -> s.forEach { c[it - 'a']++ } }.let { cnt -> (0..25).filter { cnt[it] % 2 == 1 }.let { odds -> if (odds.size > (n % 2)) "" else cnt.map { it / 2 }.let { hc -> (if (odds.isEmpty()) "" else ('a' + odds[0]).toString()).let { mid -> (0..25).map { a -> target.take(h).count { c -> c - 'a' == a } }.let { full -> (if (full == hc && (n % 2 == 0 || target[h].toString() == mid)) (target.take(h) + mid + target.take(h).reversed()).takeIf { it > target } else null) ?: (if (n % 2 == 1) h else h - 1).let { j0 -> (j0 downTo 0).firstNotNullOfOrNull { j -> if (j < h) (0..25).map { a -> hc[a] - target.take(j).count { c -> c - 'a' == a } }.let { rem -> if (rem.any { it < 0 }) null else ((target[j] - 'a' + 1)..25).firstOrNull { rem[it] > 0 }?.let { c -> rem.toMutableList().also { it[c]-- }.let { r2 -> (target.take(j) + ('a' + c) + (0..25).joinToString("") { a -> ('a' + a).toString().repeat(r2[a]) }).let { half -> half + mid + half.reversed() } } } } else (if (full == hc && mid > target[h].toString()) target.take(h) + mid + target.take(h).reversed() else null) } ?: "" } } } } } } } } }